static const char *decode_lookup_reg(const decode_reg_entry *table, uint16_t reg)
{
    size_t i;
    for (i = 0; table[i].name != NULL; i++) {
        if (table[i].reg == reg) return table[i].name;
    }
    return NULL;
}

static const char *decode_get_register_name(uint16_t machine, uint16_t reg)
{
    const char *name = NULL;
    if (reg >= 30000) {
        name = decode_lookup_reg(s_regs_allreg, reg);
        if (name) return name;
    }
    switch (machine) {
        case 0xD0: /* AMD64 / x86-64 */
        case 0x8664:
            name = decode_lookup_reg(s_regs_amd64, reg);
            if (!name) name = decode_lookup_reg(s_regs_x86, reg);
            break;
        case 0xF6: /* ARM64 */
        case 0xF8: /* ARM64EC */
        case 0xF9: /* ARM64X */
        case 0xAA64:
            name = decode_lookup_reg(s_regs_arm64, reg);
            break;
        case 0x60: /* ARM3..ARM7 */
        case 0x61:
        case 0x62:
        case 0x63:
        case 0x64:
        case 0x65:
        case 0x66:
        case 0x67:
        case 0x68:
        case 0xF0: /* THUMB */
        case 0xF4: /* ARMNT */
        case 0x01C0:
        case 0x01C2:
        case 0x01C4:
            name = decode_lookup_reg(s_regs_arm, reg);
            break;
        case 0x80: /* IA64 */
        case 0x0200:
            name = decode_lookup_reg(s_regs_ia64, reg);
            break;
        case 0x10: /* MIPS */
        case 0x0162:
        case 0x0166:
            name = decode_lookup_reg(s_regs_mips, reg);
            break;
        default: /* x86 default */
            name = decode_lookup_reg(s_regs_x86, reg);
            if (!name) name = decode_lookup_reg(s_regs_amd64, reg);
            break;
    }
    return name ? name : "UNKNOWN";
}
